#!/usr/bin/env bash
# ============================================================================
# deploy_finans_v2.sh — Finans odasi (COKME-GUVENLI v2)
#   server: /api/bi/finans/ticari-sermaye (veri) + /api/bi/finans-odasi (shell, BENZERSIZ yol) + headersSent guard
#   bi.js : Finans sekmesi -> iframe /api/bi/finans-odasi
#   Eski /api/bi/finans raporuna ve Kokpit(kokpit-iki)'ye SIFIR dokunus.
# SUNUCUDA: cd /opt/krb-assessment && bash deploy_finans_v2.sh
# Idempotent. Canli oturumsuz-yol cokme testi + tespit edilirse OTOMATIK ROLLBACK.
# Rollback yedegi: server_container.mjs.bak_v2_<ts> · bi.js.bak_v2_<ts>
# ============================================================================
set -euo pipefail
cd /opt/krb-assessment
TS=$(date +%Y%m%d_%H%M%S)

echo "== [0] shells/finans.html (base64) =="
mkdir -p shells
base64 -d > shells/finans.html <<'B64_EOF'

B64_EOF
echo "  $(wc -c < shells/finans.html) bayt"

echo "== [1] parcalari yaz =="
cat > /opt/krb-assessment/_endpoint_block_v2.js <<'EP_EOF'
  // === FINANS_ODASI_V2 — Finans odasi veri ucu + shell (COKME-GUVENLI: benzersiz yollar + headersSent guard; eski /api/bi/finans raporuna DOKUNMAZ) ===
  if (request.method === "GET" && url.pathname === "/api/bi/finans/ticari-sermaye") {
    if (response.headersSent) return;
    try {
      let session = await requireModuleAccess(request, "intelligence").catch(() => null);
      if (!session) { const _ss = await requireSahaAccess(request).catch(() => null); if (_ss && ["manager", "admin"].includes(_ss.sahaRole)) session = _ss; }
      if (!session) { if (!response.headersSent) sendJson(response, 403, { error: "yetki yok" }); return; }
      const T = session && session.tenantId;
      if (!T) { if (!response.headersSent) sendJson(response, 401, { error: "oturum yok" }); return; }
      const { rows } = await query("SELECT * FROM v_finans_ticari_sermaye WHERE tenant_id = $1::uuid", [String(T)]);
      const r = rows[0] || {};
      const MN = x => (x === null || x === undefined) ? null : Math.round(Number(x) / 1e5) / 10;
      const NM = x => (x === null || x === undefined) ? null : Number(x);
      const dio = NM(r.dio);
      let asOf; try { asOf = new Date().toLocaleDateString("tr-TR", { day: "2-digit", month: "short", year: "numeric" }); } catch (e) { asOf = null; }
      const data = {
        as_of: asOf, donem: "son 12 ay · Tem'25–Haz'26",
        net_satis_lastik: MN(r.net_satis_lastik), ciro_sirket: MN(r.ciro_tum_sirket),
        smm: MN(r.smm), brut_kar: MN(r.brut_kar), brut_marj_pct: NM(r.marj_pct),
        ticari_alacaklar: MN(r.ar_net), net_gecikmis: MN(r.net_gecikmis), finansman_yillik: MN(r.finansman_yil),
        stok_lastik: MN(r.stok_deger), ticari_borclar: MN(r.ap_borc),
        dso: NM(r.dso), dio: dio, dpo: NM(r.dpo), ccc: NM(r.ccc),
        devir: (dio && dio > 0) ? Math.round(365 / dio * 10) / 10 : null,
        twc: MN(r.twc), bagli_sermaye_pct: NM(r.bagli_sermaye_oran)
      };
      if (!response.headersSent) sendJson(response, 200, { data });
    } catch (e) { console.error("[finans-ticari-sermaye]", e && e.message); if (!response.headersSent) sendJson(response, 500, { error: String(e && e.message) }); }
    return;
  }
  if (request.method === "GET" && url.pathname === "/api/bi/finans-odasi") { /* FINANS_ODASI_SHELL_V2 */
    if (response.headersSent) return;
    try {
      const _h = await readFile("/app/shells/finans.html", "utf8");
      response.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      response.end(_h);
    } catch (e) { if (!response.headersSent) sendJson(response, 404, { error: "finans odasi bulunamadi" }); }
    return;
  }
EP_EOF
cat > /opt/krb-assessment/_patch_server_v2.py <<'PS_EOF'
import sys
F="/opt/krb-assessment/server_container.mjs"; B="/opt/krb-assessment/_endpoint_block_v2.js"; MARK="FINANS_ODASI_V2"
s=open(F,encoding="utf-8").read()
if MARK in s: print("[srv] ZATEN YAMALI — atlaniyor"); sys.exit(0)
anchor='  // KOKPIT2_PREVIEW_ROUTE — yeni kokpit onizleme (canliya dokunmaz)'
n=s.count(anchor)
if n!=1: print("[srv] ANCHOR sayisi=%d (1 olmali) — DURDU"%n); sys.exit(2)
ins=open(B,encoding="utf-8").read()
if not ins.endswith("\n"): ins+="\n"
open(F,"w",encoding="utf-8").write(s.replace(anchor, ins+anchor, 1))
print("[srv] OK — v2 uc+shell (benzersiz yol + guard) eklendi")
PS_EOF
cat > /opt/krb-assessment/_bitab_patch_v2.py <<'PB_EOF'
import sys
F="/opt/krb-assessment/shells/bi.js"; MARK="FINANS_TAB_V2"
s=open(F,encoding="utf-8").read()
if MARK in s: print("[bitab] ZATEN YAMALI — atlaniyor"); sys.exit(0)
anchorA=('          <button class="vmo-tab" data-dept="brain" style="--c:#e11d48">\n'
         '            <span>\U0001F9E0</span> CEO Assistant\n'
         '          </button>')
if s.count(anchorA)!=1: print("[bitab] ANCHOR-A sayisi!=1 — DURDU"); sys.exit(2)
btn=anchorA+'\n          <button class="vmo-tab" data-dept="finansodasi" style="--c:#059669" title="Finans Odasi" data-mark="'+MARK+'"><span>\U0001F4B0</span> Finans</button>'
s=s.replace(anchorA, btn, 1)
anchorB='  var _METRIK_TANIM = {'
if s.count(anchorB)!=1: print("[bitab] ANCHOR-B sayisi!=1 — DURDU"); sys.exit(3)
block=("  // "+MARK+" — ayri 'Finans Odasi' sekmesi (dept=finansodasi) -> iframe /api/bi/finans-odasi; eski /api/bi/finans raporuna ve Kokpit'e DOKUNMAZ\n"
"  {\n"
"    const _o = container.querySelector('.vmo-office');\n"
"    if (_o && !document.getElementById('vmo-room-finansodasi')) {\n"
"      const _fo = document.createElement('div');\n"
"      _fo.id = 'vmo-room-finansodasi';\n"
"      _fo.dataset.dept = 'finansodasi';\n"
"      _fo.className = 'vmo-room vmo-room-hidden';\n"
"      _fo.style.cssText = 'background:var(--zemin-0);color:var(--tx-0);overflow-y:auto;padding:0';\n"
"      _fo.innerHTML = '<iframe id=\"finansodasi-frame\" src=\"/api/bi/finans-odasi\" style=\"width:100%;height:100%;min-height:82vh;border:0;display:block;background:#0a0e14\" title=\"Finans Odasi\"></iframe>';\n"
"      try { _fo.style.padding = '0'; } catch (e) {}\n"
"      _o.appendChild(_fo);\n"
"    }\n"
"  }\n\n")
open(F,"w",encoding="utf-8").write(s.replace(anchorB, block+anchorB, 1))
print("[bitab] OK — Finans sekmesi + finansodasi odasi (iframe /api/bi/finans-odasi) eklendi")
PB_EOF

echo "== [2] yedek (shells DISINA -> image kirlenmez) + yama =="
cp server_container.mjs "server_container.mjs.bak_v2_$TS"
cp shells/bi.js "bi.js.bak_v2_$TS"
echo "  yedek: server_container.mjs.bak_v2_$TS · bi.js.bak_v2_$TS"
python3 /opt/krb-assessment/_patch_server_v2.py
python3 /opt/krb-assessment/_bitab_patch_v2.py

echo "== [3] node --check =="
if node --check server_container.mjs; then echo "  server OK"; else echo "  server FAIL — rollback"; cp "server_container.mjs.bak_v2_$TS" server_container.mjs; cp "bi.js.bak_v2_$TS" shells/bi.js; exit 1; fi
cp shells/bi.js /tmp/bi_c.mjs
if node --check shells/bi.js 2>/dev/null; then echo "  bi.js .js OK"; elif node --check /tmp/bi_c.mjs 2>/dev/null; then echo "  bi.js .mjs OK"; else echo "  bi.js FAIL — rollback"; cp "bi.js.bak_v2_$TS" shells/bi.js; cp "server_container.mjs.bak_v2_$TS" server_container.mjs; exit 1; fi
echo "  host: srv $(grep -c FINANS_ODASI_V2 server_container.mjs) · bi.js $(grep -c FINANS_TAB_V2 shells/bi.js)"

echo "== [4] build + deploy =="
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 5

echo "== [5] KONTEYNER + COKME-GUVENLIGI TESTI (oturumsuz) =="
echo "  container : $(docker ps --filter name=krb-assessment --format '{{.Status}}')"
echo "  srv marker: $(docker exec krb-assessment grep -c FINANS_ODASI_V2 /app/server.mjs)  bi.js marker: $(docker exec krb-assessment grep -c FINANS_TAB_V2 /app/shells/bi.js)"
echo "  finans.html(image): $(docker exec krb-assessment sh -c 'wc -c < /app/shells/finans.html') bayt"
echo "  /api/bi/finans-odasi (shell 200 bekle)       : $(curl -s -o /dev/null -w '%{http_code}' http://localhost:8080/api/bi/finans-odasi)"
echo "  /api/bi/finans/ticari-sermaye (403/401 bekle): $(curl -s -o /dev/null -w '%{http_code}' http://localhost:8080/api/bi/finans/ticari-sermaye)"
echo "  /api/bi/finans (ESKI rapor, dokunulmadi)     : $(curl -s -o /dev/null -w '%{http_code}' http://localhost:8080/api/bi/finans)"
echo "  --- ardarda vurup cokme kontrolu ---"
for i in 1 2 3 4 5; do curl -s -o /dev/null http://localhost:8080/api/bi/finans-odasi || true; curl -s -o /dev/null http://localhost:8080/api/bi/finans/ticari-sermaye || true; curl -s -o /dev/null http://localhost:8080/api/bi/finans || true; done
sleep 2
HS=$(docker logs --since 90s krb-assessment 2>&1 | grep -c ERR_HTTP_HEADERS_SENT || true)
UP=$(docker ps --filter name=krb-assessment --format '{{.Status}}')
echo "  ERR_HTTP_HEADERS_SENT (0 bekle): $HS"
echo "  container hala ayakta          : $UP"
if [ "$HS" != "0" ]; then echo "  !!! COKME TESPIT — OTOMATIK ROLLBACK !!!"; cp "server_container.mjs.bak_v2_$TS" server_container.mjs; cp "bi.js.bak_v2_$TS" shells/bi.js; docker build -t krb-assessment:secure . >/dev/null 2>&1 && docker compose up -d --force-recreate krb-assessment; echo "  geri alindi (eski hale)."; exit 1; fi

echo "== [6] FINGERPRINT =="
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform <<'SQL_EOF'
INSERT INTO bi_insa_gunlugu (adim, ne, neden, detay)
SELECT 'FINANS_ODASI_V2','Finans odasi yeniden: veri ucu /api/bi/finans/ticari-sermaye + shell /api/bi/finans-odasi (BENZERSIZ yol) + her yanitta headersSent guard','V1 shell yolu /api/bi/finans eski (return-suz) rapor uacuyla cakisti -> ERR_HTTP_HEADERS_SENT -> surec cokup oturumlar dustu -> kokpit karardi. Rollback yapildi; v2 benzersiz yol + guard ile cokme-guvenli','{"marker":"FINANS_ODASI_V2","uc":["/api/bi/finans/ticari-sermaye","/api/bi/finans-odasi"],"kaynak":"v_finans_ticari_sermaye","incident":"path-collision-double-response","fix":"unique-path+headersSent-guard"}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM bi_insa_gunlugu WHERE adim='FINANS_ODASI_V2');

INSERT INTO bi_insa_gunlugu (adim, ne, neden, detay)
SELECT 'FINANS_TAB_V2','BI masaustu (bi.js) Finans sekmesi: dept=finansodasi -> iframe /api/bi/finans-odasi','Finans odasini ust menude gorunur kilar; benzersiz yola baglandi (V1 cakismasi giderildi)','{"marker":"FINANS_TAB_V2","dosya":"shells/bi.js","iframe":"/api/bi/finans-odasi"}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM bi_insa_gunlugu WHERE adim='FINANS_TAB_V2');

INSERT INTO bi_yetenek (ad,tur,ne_ise_yarar,nasil,cekmece,durum,guven,kanit,aktif,eklendi_at,guncellendi_at,son_gorulme)
SELECT 'finans_ticari_sermaye','uc','Finans odasi kanonik ticari-sermaye/CCC veri ucu; v_finans_ticari_sermaye viewini tenant bazli okur, milyon-olcekli JSON doner. headersSent guard ile cokme-guvenli.','GET /api/bi/finans/ticari-sermaye (requireModuleAccess intelligence / saha manager-admin)','finans','canli','taslak','{"marker":"FINANS_ODASI_V2","kaynak":"v_finans_ticari_sermaye"}'::jsonb,true,now(),now(),now()
WHERE NOT EXISTS (SELECT 1 FROM bi_yetenek WHERE ad='finans_ticari_sermaye');

INSERT INTO bi_yetenek (ad,tur,ne_ise_yarar,nasil,cekmece,durum,guven,kanit,aktif,eklendi_at,guncellendi_at,son_gorulme)
SELECT 'finans_odasi_shell','rapor','Finans odasi UI (4 alt-oda), veri-gudumlu; BENZERSIZ yol /api/bi/finans-odasi ile servis (eski /api/bi/finans raporundan ayri).','GET /api/bi/finans-odasi','finans','canli','taslak','{"marker":"FINANS_ODASI_V2","dosya":"shells/finans.html"}'::jsonb,true,now(),now(),now()
WHERE NOT EXISTS (SELECT 1 FROM bi_yetenek WHERE ad='finans_odasi_shell');

INSERT INTO bi_yetenek (ad,tur,ne_ise_yarar,nasil,cekmece,durum,guven,kanit,aktif,eklendi_at,guncellendi_at,son_gorulme)
SELECT 'finans_odasi_tab','rapor','BI masaustu ust menusunde Finans sekmesi (dept=finansodasi); /api/bi/finans-odasi odasini iframe ile acar. Kokpit(kokpit-iki) ve eski finans raporundan ayri.','shells/bi.js nav butonu -> vmo-room-finansodasi iframe /api/bi/finans-odasi','finans','canli','taslak','{"marker":"FINANS_TAB_V2","dosya":"shells/bi.js"}'::jsonb,true,now(),now(),now()
WHERE NOT EXISTS (SELECT 1 FROM bi_yetenek WHERE ad='finans_odasi_tab');

INSERT INTO bi_yetenek (ad,tur,ne_ise_yarar,nasil,cekmece,durum,guven,kanit,aktif,eklendi_at,guncellendi_at,son_gorulme)
SELECT 'v_finans_ticari_sermaye','tablo','Finans odasi tek dogruluk kaynagi view: tenant bazli ticari sermaye/CCC kanonu (stok LASTIK% filtreli, kokpitle mutabik).','SELECT * FROM v_finans_ticari_sermaye WHERE tenant_id = <uuid>','finans','canli','onayli','{"tur":"view","marker":"FINANS_ODASI_V2"}'::jsonb,true,now(),now(),now()
WHERE NOT EXISTS (SELECT 1 FROM bi_yetenek WHERE ad='v_finans_ticari_sermaye');
SQL_EOF
echo "== [6b] dogrulama =="
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -c "SELECT adim FROM bi_insa_gunlugu WHERE adim IN ('FINANS_ODASI_V2','FINANS_TAB_V2') ORDER BY adim;"
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -c "SELECT ad,durum FROM bi_yetenek WHERE ad IN ('finans_ticari_sermaye','finans_odasi_shell','finans_odasi_tab','v_finans_ticari_sermaye') ORDER BY ad;"
echo "== BITTI — v2 cokme-guvenli canli. Kokpit(kokpit-iki) ve eski /api/bi/finans raporu dokunulmadi. Tarayici: Cmd+Shift+R -> ust menude Finans. =="
